import { beforeEach, describe, expect, test, vi } from "vitest";
import { verifyEmailChangeToken } from "@/lib/jwt";
import { updateBrevoCustomer } from "@/modules/auth/lib/brevo";
import { getUser, updateUser } from "@/modules/auth/lib/user";
import { applyIPRateLimit } from "@/modules/core/rate-limit/helpers";
import { rateLimitConfigs } from "@/modules/core/rate-limit/rate-limit-configs";
import { verifyEmailChangeAction } from "./actions";

type VerifyEmailChangeHandler = (args: {
  ctx: { auditLoggingCtx: { userId?: string; oldObject?: unknown; newObject?: unknown } };
  parsedInput: { token: string };
}) => Promise<unknown>;

vi.mock("@/lib/jwt", () => ({
  verifyEmailChangeToken: vi.fn(),
}));

vi.mock("@/lib/utils/action-client", () => ({
  actionClient: {
    inputSchema: vi.fn().mockReturnThis(),
    action: vi.fn((handler: VerifyEmailChangeHandler) => handler),
  },
}));

vi.mock("@/modules/auth/lib/brevo", () => ({
  updateBrevoCustomer: vi.fn(),
}));

vi.mock("@/modules/auth/lib/user", () => ({
  getUser: vi.fn(),
  updateUser: vi.fn(),
}));

vi.mock("@/modules/core/rate-limit/helpers", () => ({
  applyIPRateLimit: vi.fn(),
}));

vi.mock("@/modules/ee/audit-logs/lib/handler", () => ({
  withAuditLogging: vi.fn((_action: string, _object: string, handler: VerifyEmailChangeHandler) => handler),
}));

describe("verifyEmailChangeAction", () => {
  const parsedInput = { token: "opaque-email-change-token" };
  const mockCtx = { auditLoggingCtx: {} };

  beforeEach(() => {
    vi.resetAllMocks();
    vi.mocked(applyIPRateLimit).mockResolvedValue({ allowed: true });
    vi.mocked(verifyEmailChangeToken).mockResolvedValue({ id: "user-123", email: "new@example.com" });
    vi.mocked(getUser).mockResolvedValue({ id: "user-123", email: "old@example.com" } as never);
    vi.mocked(updateUser).mockResolvedValue({ id: "user-123", email: "new@example.com" } as never);
    vi.mocked(updateBrevoCustomer).mockResolvedValue(undefined);
  });

  test("applies the verification IP limit before verifying the token", async () => {
    await verifyEmailChangeAction({ ctx: mockCtx, parsedInput } as never);

    expect(applyIPRateLimit).toHaveBeenCalledWith(rateLimitConfigs.auth.verifyEmail);
    expect(applyIPRateLimit).toHaveBeenCalledBefore(vi.mocked(verifyEmailChangeToken));
  });

  test("short-circuits before token processing and side effects when the IP limit is exceeded", async () => {
    vi.mocked(applyIPRateLimit).mockRejectedValue(
      new Error("Maximum number of requests reached. Please try again later.")
    );

    await expect(verifyEmailChangeAction({ ctx: mockCtx, parsedInput } as never)).rejects.toThrow(
      "Maximum number of requests reached. Please try again later."
    );
    expect(verifyEmailChangeToken).not.toHaveBeenCalled();
    expect(getUser).not.toHaveBeenCalled();
    expect(updateUser).not.toHaveBeenCalled();
    expect(updateBrevoCustomer).not.toHaveBeenCalled();
  });
});

import { beforeEach, describe, expect, test, vi } from "vitest";
import { createSetupCheckoutSession } from "./create-setup-checkout-session";

const mocks = vi.hoisted(() => ({
  subscriptionsRetrieve: vi.fn(),
  checkoutSessionsCreate: vi.fn(),
}));

vi.mock("@/lib/env", () => ({
  env: {
    STRIPE_SECRET_KEY: "sk_test_123",
  },
}));

vi.mock("stripe", () => ({
  default: class MockStripe {
    subscriptions = {
      retrieve: mocks.subscriptionsRetrieve,
    };
    checkout = {
      sessions: {
        create: mocks.checkoutSessionsCreate,
      },
    };
  },
}));

describe("createSetupCheckoutSession", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mocks.subscriptionsRetrieve.mockResolvedValue({ currency: "usd" });
    mocks.checkoutSessionsCreate.mockResolvedValue({ url: "https://checkout.stripe.test/setup" });
  });

  test("creates payment-only setup checkout without upgrade metadata", async () => {
    const url = await createSetupCheckoutSession(
      "cus_1",
      "sub_1",
      "https://app.formbricks.com/workspaces/ws_1/settings/organization/billing",
      "org_1"
    );

    expect(url).toBe("https://checkout.stripe.test/setup");
    expect(mocks.checkoutSessionsCreate).toHaveBeenCalledWith(
      expect.objectContaining({
        success_url:
          "https://app.formbricks.com/workspaces/ws_1/settings/organization/billing?checkout_success=1",
        metadata: {
          organizationId: "org_1",
          subscriptionId: "sub_1",
        },
      })
    );
  });

  test("creates setup checkout with upgrade metadata and pending success flag", async () => {
    await createSetupCheckoutSession(
      "cus_1",
      "sub_1",
      "https://app.formbricks.com/workspaces/ws_1/settings/organization/billing",
      "org_1",
      {
        targetPlan: "scale",
        targetInterval: "monthly",
      }
    );

    expect(mocks.checkoutSessionsCreate).toHaveBeenCalledWith(
      expect.objectContaining({
        success_url:
          "https://app.formbricks.com/workspaces/ws_1/settings/organization/billing?checkout_success=1&upgrade_pending=1&session_id={CHECKOUT_SESSION_ID}",
        metadata: {
          organizationId: "org_1",
          subscriptionId: "sub_1",
          targetPlan: "scale",
          targetInterval: "monthly",
        },
      })
    );
  });

  // ENG-3370: the upgrade is confirmed with confirmCardPayment and may replace a legacy EUR subscription
  // with a USD one, so the checkout must not offer a method (e.g. SEPA for EUR) that can't pay it.
  test("restricts an upgrade checkout to cards, even for a EUR subscription", async () => {
    mocks.subscriptionsRetrieve.mockResolvedValue({ currency: "eur" });

    await createSetupCheckoutSession("cus_1", "sub_1", "https://app.formbricks.com/billing", "org_1", {
      targetPlan: "pro",
      targetInterval: "monthly",
    });

    expect(mocks.checkoutSessionsCreate).toHaveBeenCalledWith(
      expect.objectContaining({ payment_method_types: ["card"] })
    );
  });

  test("leaves a card-only (no upgrade) checkout on the account's payment methods", async () => {
    await createSetupCheckoutSession("cus_1", "sub_1", "https://app.formbricks.com/billing", "org_1");

    expect(mocks.checkoutSessionsCreate.mock.calls[0][0]).not.toHaveProperty("payment_method_types");
  });
});

import { describe, expect, test } from "vitest";
import { OrganizationAccessType } from "@formbricks/types/api-key";
import {
  getFeedbackDirectoryAssignmentAuthorizationAction,
  getFeedbackDirectoryAuthorizationAction,
  getOrganizationAuthorizationActionForAccessType,
  getWorkspaceAuthorizationAction,
  getWorkspaceAuthorizationActionForMethod,
} from "./permission-action";

describe("semantic authorization action mapping", () => {
  test.each([
    [undefined, "workspace.read"],
    ["read", "workspace.read"],
    ["readWrite", "workspace.write"],
    ["manage", "workspace.manage"],
  ] as const)("maps workspace permission %s", (permission, action) => {
    expect(getWorkspaceAuthorizationAction(permission)).toBe(action);
  });

  test.each([
    ["GET", "workspace.read"],
    ["POST", "workspace.write"],
    ["PUT", "workspace.write"],
    ["PATCH", "workspace.write"],
    ["DELETE", "workspace.manage"],
  ] as const)("maps HTTP %s", (method, action) => {
    expect(getWorkspaceAuthorizationActionForMethod(method)).toBe(action);
  });

  test.each([
    [OrganizationAccessType.Read, "organization.read_access"],
    [OrganizationAccessType.Write, "organization.manage_access"],
  ] as const)("maps organization access %s", (accessType, action) => {
    expect(getOrganizationAuthorizationActionForAccessType(accessType)).toBe(action);
  });

  test.each([
    ["read", "feedbackDirectory.read"],
    ["write", "feedbackDirectory.write"],
    ["manage", "feedbackDirectory.manage"],
  ] as const)("maps directory %s to the central vocabulary", (permission, action) => {
    expect(getFeedbackDirectoryAuthorizationAction(permission)).toBe(action);
  });

  test.each([
    [undefined, "feedbackDirectoryAssignment.read"],
    ["read", "feedbackDirectoryAssignment.read"],
    ["readWrite", "feedbackDirectoryAssignment.write"],
    ["manage", "feedbackDirectoryAssignment.manage"],
  ] as const)("maps assignment %s to the central vocabulary", (permission, action) => {
    expect(getFeedbackDirectoryAssignmentAuthorizationAction(permission)).toBe(action);
  });
});

import { beforeEach, describe, expect, test, vi } from "vitest";
import { createEmailToken } from "@/lib/jwt";
import { getUserByEmail } from "@/lib/user/service";
import { createEmailTokenAction } from "./actions";

vi.mock("@/lib/jwt", () => ({
  createEmailToken: vi.fn(),
}));

vi.mock("@/lib/user/service", () => ({
  getUserByEmail: vi.fn(),
}));

vi.mock("@/lib/utils/action-client", () => ({
  actionClient: {
    inputSchema: vi.fn().mockReturnThis(),
    action: vi.fn((fn) => fn),
  },
}));

describe("createEmailTokenAction", () => {
  beforeEach(() => {
    vi.resetAllMocks();
  });

  test("normalizes mixed-case email lookup and mints a token for the stored email", async () => {
    vi.mocked(getUserByEmail).mockResolvedValue({ email: "ada@example.com" } as never);
    vi.mocked(createEmailToken).mockReturnValue("email-token");

    const result = await createEmailTokenAction({
      parsedInput: { email: "Ada@Example.com" },
    } as never);

    expect(getUserByEmail).toHaveBeenCalledWith("ada@example.com");
    expect(createEmailToken).toHaveBeenCalledWith("ada@example.com");
    expect(result).toBe("email-token");
  });

  test("rejects token creation when no matching user exists", async () => {
    vi.mocked(getUserByEmail).mockResolvedValue(null);

    await expect(
      createEmailTokenAction({
        parsedInput: { email: "Ada@Example.com" },
      } as never)
    ).rejects.toThrow("Invalid request");
    expect(createEmailToken).not.toHaveBeenCalled();
  });
});

"use server";

import { z } from "zod";
import { verifyEmailChangeToken } from "@/lib/jwt";
import { actionClient } from "@/lib/utils/action-client";
import { updateBrevoCustomer } from "@/modules/auth/lib/brevo";
import { getUser, updateUser } from "@/modules/auth/lib/user";
import { applyIPRateLimit } from "@/modules/core/rate-limit/helpers";
import { rateLimitConfigs } from "@/modules/core/rate-limit/rate-limit-configs";
import { withAuditLogging } from "@/modules/ee/audit-logs/lib/handler";

export const verifyEmailChangeAction = actionClient.inputSchema(z.object({ token: z.string() })).action(
  withAuditLogging("updated", "user", async ({ ctx, parsedInput }) => {
    await applyIPRateLimit(rateLimitConfigs.auth.verifyEmail);

    // Unauthenticated on purpose — the link is clicked from the new mailbox, often in another browser.
    // What makes that safe is the token's binding to the credential state it was issued under
    // (verifyEmailChangeToken), so a password reset or a prior email change kills it (ENG-2106).
    const { id, email } = await verifyEmailChangeToken(parsedInput.token);

    if (!email) {
      throw new Error("Email not found in token");
    }
    const oldObject = await getUser(id);
    const user = await updateUser(id, { email, emailVerified: true });
    if (!user) {
      throw new Error("User not found or email update failed");
    }

    ctx.auditLoggingCtx.userId = id;
    ctx.auditLoggingCtx.oldObject = oldObject;
    ctx.auditLoggingCtx.newObject = user;

    await updateBrevoCustomer({ id: user.id, email: user.email });
    return user;
  })
);

import { beforeEach, describe, expect, test, vi } from "vitest";
import { z } from "zod";
import { logger } from "@formbricks/logger";
import { logSignOut } from "@/modules/auth/lib/utils";
import { logSignOutAction } from "./sign-out";

const { sessionUser } = vi.hoisted(() => ({ sessionUser: { id: "user123", email: "test@example.com" } }));

vi.mock("@formbricks/logger", () => ({
  logger: {
    error: vi.fn(),
  },
}));

vi.mock("@/modules/auth/lib/utils", () => ({
  logSignOut: vi.fn(),
}));

// Runs the handler the way next-safe-action does: parse the input with the action's schema, then hand
// the authenticated user over in ctx.
vi.mock("@/lib/utils/action-client", () => ({
  authenticatedActionClient: {
    inputSchema: (schema: z.ZodType) => ({
      action:
        (fn: (args: { ctx: unknown; parsedInput: unknown }) => Promise<unknown>) => async (input: unknown) =>
          fn({ ctx: { user: sessionUser }, parsedInput: schema.parse(input) }),
    }),
  },
}));

// Clear the existing mock from vitestSetup.ts
vi.unmock("@/modules/auth/actions/sign-out");

const callAction = (input: unknown) =>
  (logSignOutAction as unknown as (input: unknown) => Promise<unknown>)(input);

describe("logSignOutAction", () => {
  const mockContext = {
    reason: "user_initiated" as const,
    redirectUrl: "https://example.com",
    organizationId: "clxyz1234567890abcdefghij",
  };

  beforeEach(() => {
    vi.clearAllMocks();
  });

  test("logs the sign-out for the session user", async () => {
    await callAction(mockContext);

    expect(logSignOut).toHaveBeenCalledWith(sessionUser.id, sessionUser.email, mockContext);
    expect(logSignOut).toHaveBeenCalledTimes(1);
  });

  test("logs the session user regardless of extra input fields", async () => {
    await callAction({ ...mockContext, userId: "victim", userEmail: "victim@example.com" });

    expect(logSignOut).toHaveBeenCalledWith(sessionUser.id, sessionUser.email, mockContext);
  });

  test("rejects an unknown reason", async () => {
    await expect(callAction({ reason: "anything" })).rejects.toThrow();
    expect(logSignOut).not.toHaveBeenCalled();
  });

  test("logs error and re-throws when logSignOut throws", async () => {
    const mockError = new Error("Failed to log sign out");
    vi.mocked(logSignOut).mockImplementation(() => {
      throw mockError;
    });

    await expect(callAction(mockContext)).rejects.toThrow(mockError);

    expect(logger.error).toHaveBeenCalledWith(
      {
        userId: sessionUser.id,
        context: mockContext,
        error: mockError.message,
      },
      "Failed to log sign out event"
    );
  });
});
